//! Atomic RTL_RUN_ONCE primitives using the native x64 one-word representation.
use core::sync::atomic::{AtomicUsize,Ordering};
const SUCCESS:i32=0;const PENDING:i32=0x00000103;const UNSUCCESSFUL:i32=0xC0000001u32 as i32;const INVALID:i32=0xC000000Du32 as i32;
const STATE_PENDING:usize=1;const STATE_COMPLETE:usize=2;const STATE_MASK:usize=3;const CHECK_ONLY:u32=1;const INIT_FAILED:u32=4;
#[inline] unsafe fn atom(p:*mut usize)->Option<&'static AtomicUsize>{if p.is_null()||((p as usize)&(core::mem::align_of::<usize>()-1))!=0{None}else{Some(unsafe{&*(p as *const AtomicUsize)})}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_run_once_initialize(p:*mut usize){if !p.is_null(){unsafe{core::ptr::write_volatile(p,0);}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_run_once_begin_initialize(p:*mut usize,flags:u32,context:*mut *mut core::ffi::c_void)->i32{if flags&!(CHECK_ONLY|2)!=0||context.is_null(){return INVALID;}let Some(a)=(unsafe{atom(p)})else{return INVALID;};loop{let v=a.load(Ordering::Acquire);if v&STATE_COMPLETE!=0{unsafe{*context=(v&!STATE_MASK) as *mut core::ffi::c_void;}return SUCCESS;}if v&STATE_PENDING!=0{unsafe{*context=core::ptr::null_mut();}return UNSUCCESSFUL;}if flags&CHECK_ONLY!=0{unsafe{*context=core::ptr::null_mut();}return UNSUCCESSFUL;}if a.compare_exchange(v,STATE_PENDING,Ordering::AcqRel,Ordering::Acquire).is_ok(){unsafe{*context=core::ptr::null_mut();}return PENDING;}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_run_once_complete(p:*mut usize,flags:u32,context:*mut core::ffi::c_void)->i32{if flags&!(INIT_FAILED|2)!=0{return INVALID;}let Some(a)=(unsafe{atom(p)})else{return INVALID;};if a.load(Ordering::Acquire)&STATE_PENDING==0{return INVALID;}let v=if flags&INIT_FAILED!=0{0}else{(context as usize&!STATE_MASK)|STATE_COMPLETE};a.store(v,Ordering::Release);SUCCESS}
pub type RunOnceCallback=unsafe extern "win64" fn(*mut usize,*mut core::ffi::c_void,*mut *mut core::ffi::c_void)->u32;
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_run_once_execute_once(p:*mut usize,callback:Option<RunOnceCallback>,parameter:*mut core::ffi::c_void,context:*mut *mut core::ffi::c_void)->i32{let Some(cb)=callback else{return INVALID;};if context.is_null(){return INVALID;}let mut existing=core::ptr::null_mut();let st=unsafe{rtl_run_once_begin_initialize(p,0,&mut existing)};if st==SUCCESS{unsafe{*context=existing;}SUCCESS}else if st==PENDING{let mut produced=core::ptr::null_mut();let result=unsafe{cb(p,parameter,&mut produced)};if result!=0{let c=if produced.is_null(){parameter}else{produced};let done=unsafe{rtl_run_once_complete(p,0,c)};if done<0{return done;}unsafe{*context=c;}SUCCESS}else{let _=unsafe{rtl_run_once_complete(p,INIT_FAILED,core::ptr::null_mut())};UNSUCCESSFUL}}else{st}}
